import { Injectable } from '@angular/core';
import { ApiServiceService } from '../../../../services/api/api-service.service';
import { firstValueFrom } from 'rxjs';
import { Credito } from '../../../../models/credito.model';
import { UtilsService } from '../../../../services/utils.service';

@Injectable({
  providedIn: 'root'
})
export class BuscadorCreditosService {
  private cache = new Map<string, { timestamp: number, data: Promise<Credito[]> }>();
  private nombreCache = new Map<number, string>();
  private readonly CACHE_EXPIRATION_MS = 5 * 60 * 1000; // 5 minutos

  constructor(
    private api: ApiServiceService,
    private utils: UtilsService,
  ) { }

  public async autoCompleteCreditos(search: string = '', relations: string[] = []): Promise<Credito[]> {
    const cacheKey = this.generateCacheKey(search, relations);
    const now = Date.now();

    // Verificar si existe en cache y no ha expirado
    if (this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey)!;
      if (now - cached.timestamp < this.CACHE_EXPIRATION_MS) {
        return cached.data;
      }
    }

    // Si no está en cache o ha expirado, hacer nueva solicitud
    const promise = firstValueFrom(
      this.api.get<Credito[]>('api/creditos/filtros/autocomplete', {
        conditionals: JSON.stringify([
          ['deleted_at', 'IS NULL', null]
        ]),
        relations: JSON.stringify(relations),
        filtro: search,
        per_page: 500,
        page: 1,
      }, false)
    ).then(response => response.data ?? []);

    // Actualizar cache
    this.cache.set(cacheKey, {
      timestamp: now,
      data: promise
    });

    return promise;
  }

  public async nombreClienteFromCreditoId(id: number | undefined) {
    if (!id) return;
    const data = await this.autoCompleteCreditos(id.toString())

    if (!data.length) return

    return this.utils.nombreClienteFromCredito(data[0])
  }

  public async obtenerCreditosPorIds(ids: number[]): Promise<Map<number, string>> {
    if (ids.length === 0) return new Map();

    const uniqueIds = [...new Set(ids)];
    const idString = uniqueIds.join(',');

    const response = await firstValueFrom(
      this.api.get<Credito[]>('api/creditos/filtros/autocomplete', { ids: idString, per_page: 1000 })
    );

    const nombresMap = new Map<number, string>();

    (response.data || []).forEach(credito => {
      const nombre = this.utils.nombreClienteFromCredito(credito);
      nombresMap.set(credito.id, nombre);
      this.nombreCache.set(credito.id, nombre); // actualizar caché
    });

    // Asegurar que todos los IDs solicitados estén en el mapa
    uniqueIds.forEach(id => {
      if (!nombresMap.has(id)) {
        nombresMap.set(id, 'Cliente no encontrado');
      }
    });

    return nombresMap;
  }

  private generateCacheKey(search: string, relations: string[]): string {
    const relationsKey = relations.sort().join(',');
    return `${search.toUpperCase().trim()}|${relationsKey}`;
  }

  // Método opcional para limpiar cache manualmente
  public clearCache(): void {
    this.cache.clear();
  }

  // Método opcional para limpiar entradas expiradas
  public cleanExpiredCache(): void {
    const now = Date.now();
    for (const [key, value] of this.cache.entries()) {
      if (now - value.timestamp > this.CACHE_EXPIRATION_MS) {
        this.cache.delete(key);
      }
    }
  }
}